BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — "clearly trivial" threshold definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does the term "clearly trivial" mean when applied to misstatements identified during an audit?', '["Misstatements that are smaller than the amount the auditor would not accumulate", "Misstatements that management has already corrected before year-end", "Misstatements found only in footnote disclosures rather than financial statements", "Misstatements that fall below the overall materiality threshold"]'::jsonb, 0, 'AU-C 450.A2 defines "clearly trivial" as amounts the auditor designates below which misstatements need not be accumulated. This is a threshold set well below materiality, indicating the amounts are inconsequential both individually and in aggregate. Unlike choice D, "clearly trivial" is distinct from and substantially lower than the materiality threshold itself.', 'easy', 1),

-- Q2: hard / L3 — pattern of misstatements suggesting bias
(1, 'Misstatements and Control Deficiencies', 'During the audit of Keystone Manufacturing, the engagement team identifies that all eight uncorrected misstatements, totaling $62,000 against a $400,000 materiality threshold, overstate net income. Each misstatement individually falls below the $50,000 tolerable misstatement level. The auditor should conclude that these misstatements most likely indicate:', '["A systematic bias in the preparation of the financial statements", "An immaterial aggregate effect requiring no further action", "Random estimation errors that cancel out over time", "Factual misstatements that require restatement of prior periods"]'::jsonb, 0, 'AU-C 450.11 requires the auditor to consider whether uncorrected misstatements indicate a bias in management''s judgments. When all misstatements move in the same direction and favor a particular outcome, this pattern suggests intentional or unintentional bias rather than random error. Unlike choice B, even though the aggregate is below materiality, the directional pattern warrants heightened scrutiny and possible opinion modification.', 'hard', 3),

-- Q3: easy / L1 — tolerable misstatement definition
(1, 'Misstatements and Control Deficiencies', 'In the context of audit sampling, what is the purpose of tolerable misstatement?', '["To set the maximum sample size for statistical sampling", "To determine the population of transactions to test", "To establish the maximum misstatement in a population the auditor can accept", "To define the threshold for communicating deficiencies to governance"]'::jsonb, 2, 'AU-C 530.A3 defines tolerable misstatement as the application of performance materiality to a specific sampling procedure. It represents the maximum amount of misstatement in a population that the auditor is willing to accept and still conclude the sampling objective is achieved. Unlike choice A, tolerable misstatement influences but does not directly set the maximum sample size.', 'easy', 1),

-- Q4: easy / L1 — auditor's clearly trivial threshold documentation
(1, 'Misstatements and Control Deficiencies', 'What must the auditor document regarding the threshold for accumulating misstatements during an audit?', '["The overall materiality amount and the basis for its calculation", "The performance materiality percentage approved by the audit committee", "The fraud risk factors identified during the planning phase", "The amount below which misstatements are regarded as clearly trivial"]'::jsonb, 3, 'AU-C 450.14 requires the auditor to document the amount below which misstatements would be regarded as clearly trivial and would not need to be accumulated. This threshold is distinct from materiality and performance materiality. Unlike choice A, while materiality documentation is required by AU-C 320, AU-C 450 specifically addresses the clearly trivial threshold as a separate documentation requirement for misstatement accumulation.', 'easy', 1),

-- Q5: hard / L4 — cumulative impact of year-end control failures on audit strategy
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinnacle Energy Corp., the senior associate discovers that the accounts payable supervisor was on extended medical leave for the last quarter. During this period, the three-way match control was not performed on $4.2 million in vendor invoices, the monthly reconciliation of the AP subledger to the general ledger was skipped, and no compensating review was assigned. Performance materiality is $350,000. The most appropriate response is to:', '["Expand substantive testing of accounts payable to compensate for the control failures and evaluate for material weakness", "Rely on the three quarters where controls operated effectively and perform limited additional procedures", "Request management correct any identified misstatements without modifying the audit approach", "Report the deficiencies as significant deficiencies since no actual misstatement has been identified"]'::jsonb, 0, 'AU-C 265.A12 and AU-C 330.16 require the auditor to evaluate the severity of control failures and design responsive procedures. Multiple simultaneous failures in AP controls over a material transaction volume without compensating controls indicate a reasonable possibility of material misstatement. Unlike choice D, the auditor must assess severity based on potential—not just actual—misstatement, and the combination likely constitutes a material weakness requiring expanded substantive procedures.', 'hard', 4),

-- Q6: medium / L3 — IT access control weakness affecting financial reporting
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bridgewater Financial Group, the IT auditor finds that four former employees retained active system access for an average of 45 days after termination. Two of these accounts had the ability to post journal entries. No unauthorized transactions were identified. The auditor should evaluate this finding as:', '["An operating deficiency that does not rise to the level of a control deficiency", "A control deficiency that should be assessed for severity as a potential significant deficiency or material weakness", "An IT observation reported only to the IT department with no audit implications", "A finding that requires immediate withdrawal from the engagement"]'::jsonb, 1, 'AU-C 265.A7 requires evaluation of IT access control weaknesses that could permit unauthorized transactions affecting financial reporting. Terminated employees retaining journal entry access represents a deficiency in operation of the user access control. The auditor must assess severity considering the magnitude of potential misstatement and likelihood. Unlike choice A, this clearly constitutes a control deficiency because the control did not operate effectively to prevent unauthorized access.', 'medium', 3),

-- Q7: hard / L4 — evaluate interplay between compensating controls and deficiency severity
(1, 'Misstatements and Control Deficiencies', 'Atlas Construction has no segregation of duties between the employee who records cash receipts and the employee who prepares the bank deposit. However, the controller performs a daily independent reconciliation of cash receipts to bank deposits, and a separate manager reviews all customer account adjustments exceeding $500. Total annual cash receipts are $18 million, and performance materiality is $200,000. In evaluating these compensating controls, the auditor should conclude that:', '["The compensating controls are irrelevant because the primary segregation failure is automatically a material weakness", "The identified deficiency is mitigated by the compensating controls but still warrants assessment of residual risk and possible classification as a significant deficiency", "The compensating controls eliminate the deficiency entirely, requiring no communication", "The deficiency should be reclassified as a design deficiency rather than an operating deficiency"]'::jsonb, 2, 'AU-C 265.A13 states compensating controls may limit the severity of a deficiency but do not automatically eliminate it. The daily reconciliation and adjustment review reduce but do not fully eliminate the risk from missing segregation of duties over material cash flows. Unlike choice A, compensating controls must be considered in the severity assessment. Unlike choice C, residual risk remains and the deficiency still warrants communication and evaluation.', 'hard', 4),

-- Q8: hard / L4 — assess adequacy of remediation of prior-year material weakness
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Cascade Retail Inc., the auditor reported a material weakness in the revenue recognition process due to lack of automated controls over sales cutoff. Management implemented a new automated system on September 1 of the current year. The fiscal year ends December 31. When evaluating whether the material weakness has been remediated, the auditor should primarily consider:', '["Whether management has formally acknowledged the remediation in the representation letter", "Whether the financial statements were restated for the prior-year cutoff errors", "The length of time the new control has operated effectively and whether sufficient audit evidence exists to evaluate its design and operation", "Whether the IT department has certified that the automated system is functioning correctly"]'::jsonb, 3, 'AU-C 265.A19 requires the auditor to evaluate whether remediated controls have operated for a sufficient period to permit testing and to conclude on operating effectiveness. A control implemented four months before year-end requires evaluation of both design adequacy and operating effectiveness over that period. Unlike choice A, management''s acknowledgment alone is insufficient; the auditor needs direct evidence of the control''s effective operation through testing.', 'hard', 4),

-- Q9: easy / L2 — identify misstatement type in scenario
(1, 'Misstatements and Control Deficiencies', 'During the audit of Silverleaf Retailers, the auditor projects a $47,000 overstatement in inventory based on test counts of a sample representing 5% of the warehouse. Management argues the projection is overstated because the errors were concentrated in one product line. This disagreement between auditor and management about the projected amount is best classified as a:', '["Factual misstatement because it is based on observed count differences", "Known misstatement that must be corrected before the audit is completed", "Projected misstatement because it arises from a management correction", "Judgmental misstatement arising from differences in estimates or projections"]'::jsonb, 3, 'AU-C 450.A4 classifies misstatements arising from differences in management''s and the auditor''s judgment about the projection methodology or amounts as judgmental misstatements. The disagreement here concerns the extent to which sample errors should be projected to the population. Unlike choice A, factual misstatements involve no uncertainty—they are clearly identified errors in specific transactions.', 'easy', 2),

-- Q10: medium / L2 — timing of control deficiency communication
(1, 'Misstatements and Control Deficiencies', 'During interim fieldwork at Highland Medical Center in September 2025, the auditor identifies a material weakness in the payroll authorization process. The audit report will be issued in March 2026. Under AU-C 265, the auditor should communicate this material weakness in writing to those charged with governance:', '["Only after the audit report is issued so the communication reflects all findings", "No later than 60 days after the audit report release date", "On a timely basis, and no later than 60 days after the report release date, but the auditor should consider whether to communicate during the audit given the significance", "Only at the annual governance meeting following the audit completion"]'::jsonb, 1, 'AU-C 265.13 requires written communication of significant deficiencies and material weaknesses no later than 60 days after the report release date. However, AU-C 265.A27 notes the auditor should consider communicating significant matters on a timely basis during the audit when immediate corrective action is warranted. Unlike choice A, the auditor should not delay communication of material weaknesses until after the audit report is issued when earlier communication could benefit the entity.', 'medium', 2),

-- Q11: easy / L1 — operating deficiency definition
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, a deficiency in the operation of an internal control exists when:', '["A necessary control has not been designed by management", "The control is not included in the entity''s documented policies and procedures", "A properly designed control does not operate effectively or is not performed by a person with appropriate authority or competence", "The cost of the control exceeds the benefit it provides to the organization"]'::jsonb, 2, 'AU-C 265.07 defines an operating deficiency as existing when a properly designed control does not operate effectively, or the person performing the control lacks the necessary authority or competence to perform effectively. This differs from choice A, which describes a design deficiency where the control itself is missing or improperly designed rather than improperly executed.', 'easy', 1),

-- Q12: medium / L3 — segregation of duties failure severity analysis
(1, 'Misstatements and Control Deficiencies', 'At Granite Point Credit Union, a single accountant initiates wire transfers, records the transactions, and performs the monthly bank reconciliation. The credit union processes approximately $52 million in wire transfers annually, and the auditor has set performance materiality at $175,000. No compensating controls exist for these functions. The auditor should most likely classify this deficiency as:', '["A control deficiency that is not a significant deficiency because no misstatement was detected", "A significant deficiency because the deficiency involves only one employee", "A material weakness because a single individual controls all phases of a material transaction cycle without compensating controls", "An operating deficiency that requires only verbal communication to management"]'::jsonb, 2, 'AU-C 265.A11 states that a material weakness exists when there is a reasonable possibility that a material misstatement will not be prevented or detected on a timely basis. Complete absence of segregation of duties over $52 million in wire transfers with no compensating controls creates a reasonable possibility of material misstatement. Unlike choice B, the severity exceeds significant deficiency given the magnitude of transactions and total lack of mitigating controls.', 'medium', 3),

-- Q13: medium / L2 — classify misstatement by financial statement assertion
(1, 'Misstatements and Control Deficiencies', 'While auditing Mapleview Corporation, the engagement team discovers that a $290,000 equipment lease signed on December 15, 2025 was not recorded until January 10, 2026. The fiscal year ends December 31, 2025. This misstatement most directly affects which financial statement assertion?', '["Valuation and allocation of the lease liability", "Rights and obligations related to the leased asset", "Presentation and disclosure of lease commitments", "Completeness of liabilities and assets at year-end"]'::jsonb, 3, 'AU-C 315.A128 identifies completeness as the assertion that all transactions and balances that should have been recorded are included. Failing to record a lease executed before year-end means both the right-of-use asset and lease liability are missing from the financial statements, directly violating the completeness assertion. Unlike choice A, the valuation assertion concerns proper measurement of amounts that are already recorded, not whether they are recorded at all.', 'medium', 2),

-- Q14: hard / L4 — evaluate adequacy of management corrective action plan
(1, 'Misstatements and Control Deficiencies', 'The auditor communicated a material weakness to Lakeshore Medical Group regarding inadequate review of complex revenue arrangements. Management responds with a corrective action plan stating they will hire an additional accountant within six months and implement quarterly revenue reviews. The auditor''s evaluation of management''s response should focus on:', '["Whether the corrective action plan has been approved by the board of directors", "Confirming that the response was received in writing within 30 days", "Whether the planned actions, if implemented effectively, would remediate the underlying cause of the material weakness and whether the timeline is reasonable", "Verifying that the additional accountant holds a CPA license"]'::jsonb, 2, 'AU-C 265.A22 indicates the auditor should evaluate whether management''s response addresses the root cause of the weakness and whether the planned remediation would prevent future material misstatements. The auditor assesses the substance and feasibility of the plan rather than procedural formalities. Unlike choice A, board approval alone does not ensure the corrective actions are sufficient to remediate the weakness; the auditor must evaluate the design of the planned controls.', 'hard', 4),

-- Q15: easy / L1 — required recipients of material weakness communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, material weaknesses identified during a financial statement audit must be communicated in writing to:', '["The external regulatory authority and the audit committee simultaneously", "Management and those charged with governance", "Only the chief executive officer and chief financial officer", "The internal audit department and the board of directors"]'::jsonb, 1, 'AU-C 265.12-13 requires written communication of material weaknesses to both management and those charged with governance. This dual communication ensures that both the operational team responsible for remediation and the oversight body are informed. Unlike choice C, the standard specifies "management" broadly and "those charged with governance" rather than limiting communication to specific executive titles.', 'easy', 1),

-- Q16: easy / L1 — form of communication for significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'The required form of communication for significant deficiencies identified during an audit is:', '["Verbal communication documented only in the auditor''s workpapers", "A formal report filed with the SEC within 10 business days", "Inclusion in the management representation letter only", "Written communication to those charged with governance"]'::jsonb, 3, 'AU-C 265.13 requires that significant deficiencies and material weaknesses be communicated in writing to those charged with governance. The written form ensures a clear record of the communication for both the entity and the auditor. Unlike choice A, verbal communication alone is insufficient for significant deficiencies; the standard explicitly mandates written communication.', 'easy', 1),

-- Q17: medium / L3 — revenue recognition control weakness severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westfield Software Inc., the auditor finds that the company has no control over the review of multi-element revenue arrangements before they are recorded. These arrangements represent $8.3 million of the company''s $24 million in annual revenue. Performance materiality is $500,000. The auditor should most likely classify this as:', '["A control deficiency that does not warrant communication because revenue is within expected ranges", "A significant deficiency requiring only verbal communication to the CFO", "A material weakness because a missing control over a material revenue stream creates a reasonable possibility of material misstatement", "An immaterial deficiency since no misstatement was actually found in the revenue balance"]'::jsonb, 2, 'AU-C 265.A10 requires the auditor to consider the magnitude of potential misstatement and the likelihood it will occur. The absence of any review control over $8.3 million in complex revenue arrangements—well above performance materiality—creates a reasonable possibility of material misstatement going undetected. Unlike choice D, the assessment is based on what could occur, not solely on whether a misstatement was actually identified during testing.', 'medium', 3),

-- Q18: medium / L3 — accounting staff turnover effect on control environment
(1, 'Misstatements and Control Deficiencies', 'Redstone Manufacturing experienced turnover of three out of four accounting department employees during the current fiscal year. The new staff received limited training and the controller reports frequent errors requiring correction in monthly close procedures. The auditor should evaluate this situation as:', '["An HR matter outside the scope of the financial statement audit", "A risk factor that may indicate control environment weaknesses requiring further evaluation of the impact on control activities and financial reporting", "A staffing issue that only affects operating efficiency, not financial reporting controls", "An automatic material weakness that must be communicated immediately"]'::jsonb, 3, 'AU-C 315.A79 identifies the control environment as the foundation for all other components of internal control. Significant staff turnover with inadequate training directly undermines competence, a key element of the control environment under the COSO framework. Unlike choice A, the auditor must evaluate how personnel changes affect the reliability of controls over financial reporting, even though hiring decisions are management''s responsibility.', 'medium', 3),

-- Q19: medium / L2 — treatment of a passed adjustment
(1, 'Misstatements and Control Deficiencies', 'While auditing Horizon Logistics, the engagement team identifies a $38,000 overstatement in prepaid insurance. Overall materiality is $500,000 and the amount is not clearly trivial. Management declines to correct the misstatement. The auditor should classify this uncorrected amount as:', '["A passed adjustment to be included on the summary of uncorrected misstatements", "An immaterial error requiring no further documentation", "A scope limitation requiring a qualified audit opinion", "A corrected misstatement that has been resolved through management''s acknowledgment"]'::jsonb, 0, 'AU-C 450.06 requires the auditor to accumulate all identified misstatements other than those that are clearly trivial. When management declines to correct a misstatement, it becomes a "passed adjustment" documented on the summary of uncorrected misstatements. Unlike choice B, even though the amount is below materiality, it must still be accumulated and evaluated in the aggregate with other uncorrected misstatements.', 'medium', 2),

-- Q20: easy / L1 — auditor responsibility for deficiencies not rising to significant deficiency level
(1, 'Misstatements and Control Deficiencies', 'When an auditor identifies control deficiencies that are not significant deficiencies or material weaknesses, the auditor is required to:', '["File a formal report with the entity''s external regulators", "Communicate these deficiencies to management, preferably in writing", "Include all deficiencies in the auditor''s report on the financial statements", "Take no action since only significant deficiencies require communication"]'::jsonb, 1, 'AU-C 265.14 states the auditor should communicate to management control deficiencies identified during the audit that are of sufficient importance to merit management''s attention, even if they do not rise to the level of significant deficiencies. This communication is typically in writing. Unlike choice D, auditing standards do not limit communication only to significant deficiencies; lesser deficiencies should also be communicated to management.', 'easy', 1),

-- Q21: medium / L2 — qualitative vs quantitative materiality of misstatement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Pharmaceuticals, the auditor finds a $12,000 misclassification between research and development expense and general administrative expense. Overall materiality is $800,000. However, the company is close to violating a debt covenant that requires maintaining R&D spending above 8% of revenue. This misstatement is most appropriately evaluated as:', '["Clearly trivial because it is far below the materiality threshold", "Immaterial and requiring no further consideration or communication", "Potentially material on a qualitative basis due to the debt covenant sensitivity despite its small quantitative amount", "A factual misstatement that automatically requires correction regardless of materiality"]'::jsonb, 2, 'AU-C 450.A16 requires the auditor to consider both quantitative and qualitative factors when evaluating misstatements. Even though $12,000 is well below the $800,000 materiality threshold, proximity to a debt covenant violation makes the misclassification qualitatively significant. Unlike choice A, the auditor cannot dismiss a misstatement as clearly trivial when qualitative factors give it outsized significance to financial statement users.', 'medium', 2),

-- Q22: medium / L2 — prior-period misstatements affecting current opinion
(1, 'Misstatements and Control Deficiencies', 'While auditing Northstar Electronics for the year ended December 31, 2025, the auditor discovers that a $175,000 expense was improperly capitalized in the prior year, causing assets to be overstated by $145,000 after depreciation. Current-year materiality is $300,000. The auditor should evaluate the prior-period misstatement by considering:', '["Its effect on the current-period financial statements, including any carryover impact on beginning balances and current-year income", "Only the current-year depreciation impact since the original error occurred in a prior period", "Whether the prior-year auditor issued an unmodified opinion, which would eliminate the need for further evaluation", "The misstatement only if management voluntarily discloses the error in the current-year footnotes"]'::jsonb, 0, 'AU-C 450.10 requires the auditor to consider the effect of uncorrected misstatements from prior periods on current-period financial statements. A capitalization error carries forward through overstated beginning balances and understated current-year depreciation expense. Unlike choice B, the auditor must consider the full carryover effect on both the balance sheet and income statement, not just the incremental current-year impact.', 'medium', 2),

-- Q23: medium / L2 — classifying deficiency by likelihood and magnitude
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Coast Distributors, the auditor identifies that monthly inventory reconciliations are performed but not reviewed by a supervisor. The warehouse processes $6 million in inventory annually. Performance materiality is $250,000. In assessing severity, the auditor determines that the likelihood of a misstatement exceeding performance materiality is more than remote but less than reasonably possible. This deficiency should be classified as:', '["A material weakness because it involves a material account balance", "An inconsequential deficiency requiring no communication", "A design deficiency with no audit implications", "A significant deficiency because the magnitude is material but the likelihood does not meet the threshold for a material weakness"]'::jsonb, 3, 'AU-C 265.A8 distinguishes between significant deficiencies and material weaknesses based on the combination of likelihood and magnitude. When the magnitude of potential misstatement is material but the likelihood is more than remote yet less than reasonably possible, the deficiency is a significant deficiency rather than a material weakness. Unlike choice A, material weakness requires a "reasonable possibility" of material misstatement, a higher likelihood threshold than what is present here.', 'medium', 2),

-- Q24: medium / L3 — management override of controls as material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Belmont Properties LLC, the auditor discovers that the CEO regularly directed the controller to record top-side journal entries to meet quarterly earnings targets, bypassing the normal review and approval process. Total adjustments during the year were $420,000 against a $600,000 materiality level. The auditor should evaluate this finding as:', '["A routine business practice within the CEO''s authority that does not constitute a control deficiency", "A material weakness because management override of controls represents a pervasive breakdown in the control environment regardless of the dollar amount", "A significant deficiency since the total adjustments are below materiality", "An internal matter between management and the board requiring no auditor action"]'::jsonb, 1, 'AU-C 265.A14 and AU-C 240.31 indicate that management override of controls is a presumed fraud risk. Systematic override of the journal entry review process by the CEO undermines the entire control environment and creates a reasonable possibility of material misstatement. Unlike choice C, the pervasive nature of management override elevates this beyond a significant deficiency regardless of whether total adjustments fall below materiality.', 'medium', 3),

-- Q25: medium / L3 — immaterial misstatement with fraud indicators
(1, 'Misstatements and Control Deficiencies', 'While auditing Oakwood Dental Group, the auditor identifies a $5,000 misstatement caused by the office manager recording personal expenses through the company''s accounts payable. Overall materiality is $150,000. The auditor should evaluate this misstatement by:', '["Dismissing it as clearly trivial since it is well below materiality and requires no further action", "Accumulating it as a passed adjustment and taking no additional steps beyond documentation", "Performing additional procedures to assess the extent of potential fraud and reconsidering the fraud risk assessment", "Reporting the misstatement directly to law enforcement before consulting with management"]'::jsonb, 3, 'AU-C 240.35 requires the auditor to evaluate whether an identified misstatement may be indicative of fraud. Even though $5,000 is well below materiality, the intentional nature of recording personal expenses as business expenses indicates potential fraud. The auditor must reassess fraud risks and consider the need for expanded procedures. Unlike choice A, the qualitative nature of an intentional misstatement by a person with access to assets precludes treating it as clearly trivial regardless of the dollar amount.', 'medium', 3),

-- Q26: medium / L2 — when to communicate accumulated misstatements to management
(1, 'Misstatements and Control Deficiencies', 'During the audit of Falcon Manufacturing, the engagement team has accumulated $280,000 in uncorrected misstatements against a materiality level of $500,000. Several new misstatements are still being evaluated. Under AU-C 450, the auditor must communicate accumulated uncorrected misstatements to management:', '["Only if the aggregate exceeds materiality at the conclusion of the audit", "Prior to evaluating the aggregate effect, so management has an opportunity to correct them", "After the audit report is issued, as part of the management letter", "Only when individual misstatements exceed performance materiality"]'::jsonb, 1, 'AU-C 450.08 requires the auditor to communicate all accumulated misstatements to management on a timely basis and request that management correct them. This communication must occur before the auditor evaluates the aggregate effect of uncorrected misstatements on the financial statements. Unlike choice A, the auditor does not wait until the aggregate exceeds materiality; the purpose is to give management the opportunity to correct misstatements at any accumulated level.', 'medium', 2),

-- Q27: medium / L3 — monitoring deficiency severity assessment
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Insurance Group, the auditor finds that the internal audit department has not performed any monitoring activities over the claims processing cycle for the past 18 months. Claims processing handles $45 million annually and involves significant estimates for loss reserves. The financial reporting controls within the claims cycle appear to be operating, but no independent monitoring has verified this. The auditor should evaluate the monitoring gap as:', '["Irrelevant because the direct controls over claims processing are functioning properly", "A significant deficiency because the absence of monitoring increases the risk that control failures may go undetected over a material process", "A minor deficiency communicated only to the internal audit manager", "Not a control deficiency because monitoring is optional under COSO"]'::jsonb, 1, 'AU-C 265.A6 and COSO framework principles identify monitoring as an essential component of internal control. The absence of monitoring over a material process for 18 months means potential control breakdowns could go undetected for extended periods. This creates more than a remote likelihood of material misstatement. Unlike choice A, the auditor cannot rely solely on the apparent operation of direct controls when no one has independently verified their continued effectiveness.', 'medium', 3),

-- Q28: medium / L2 — documentation of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Ridgeline Construction Co., the auditor has $95,000 in accumulated uncorrected misstatements against a materiality of $400,000. Management has declined to correct these amounts. Under AU-C 450, the auditor''s documentation should include:', '["Only a notation in the planning memorandum that misstatements were found but deemed immaterial", "A summary listing the nature and amount of each uncorrected misstatement, management''s reasons for not correcting them, and the auditor''s conclusion on whether they are material individually or in aggregate", "A general statement that uncorrected misstatements exist but are below materiality, without specifying amounts", "Documentation only if management provides a written explanation for declining the corrections"]'::jsonb, 2, 'AU-C 450.14 requires the auditor to document the amount below which misstatements are clearly trivial, all misstatements accumulated during the audit, management''s response to the auditor''s request to correct, and the auditor''s conclusion on whether uncorrected misstatements are material. Unlike choice A, the standard requires detailed documentation of each misstatement, not merely a general notation that misstatements were found.', 'medium', 2),

-- Q29: easy / L1 — summary of uncorrected misstatements purpose
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the summary of uncorrected misstatements that the auditor accumulates during an audit?', '["To provide evidence for evaluating whether uncorrected misstatements are material individually or in aggregate", "To serve as the auditor''s formal demand that management correct all identified errors", "To replace the need for management representations about the financial statements", "To document the auditor''s calculation of the audit fee adjustment"]'::jsonb, 0, 'AU-C 450.06 requires the auditor to accumulate identified misstatements other than those that are clearly trivial. The summary serves as the basis for evaluating whether uncorrected misstatements, individually or in aggregate, are material to the financial statements. Unlike choice B, the summary is an evaluation tool for the auditor rather than a formal demand, though the auditor does request management to correct the misstatements.', 'easy', 1),

-- Q30: hard / L4 — combined effect of multiple deficiencies across cycles
(1, 'Misstatements and Control Deficiencies', 'During the audit of Evergreen Holdings Inc., the auditor identifies the following: (1) the purchasing department does not verify vendor existence before setting up new vendors, (2) the accounts payable clerk can both record invoices and authorize payments without supervisory review, and (3) the bank reconciliation preparer has unrestricted access to the accounts payable module. No individual deficiency has resulted in a detected misstatement above $20,000. Performance materiality is $300,000. The auditor should evaluate these deficiencies by:', '["Assessing each deficiency independently and communicating them separately as minor control deficiencies", "Determining that no communication is required because no material misstatement was actually identified", "Considering whether the combination of related deficiencies constitutes a material weakness even though each individually may not", "Reporting all three as significant deficiencies without further evaluation of their combined effect"]'::jsonb, 2, 'AU-C 265.A15 requires the auditor to consider whether a combination of control deficiencies affecting the same significant account or disclosure could collectively constitute a significant deficiency or material weakness. These three deficiencies create a pathway where fictitious vendors could be established, invoices recorded, payments authorized, and the resulting discrepancies concealed. Unlike choice A, evaluating these deficiencies in isolation would fail to capture the compounding risk across the expenditure cycle.', 'hard', 4)
;

COMMIT;
